message.content:
{
  "description": "The creature is a single chimeric animal shown in profile facing to the right, standing in a slightly crouched posture on a small patch of bare ground with sparse grass. The uppermost part is the head of a red fox with reddish-brown fur, a white muzzle and chin, a black nose, amber eyes and whiskers, which merges at the neck into the body of a barn owl. The chest, throat and front are covered in dense white and buff owl plumage with small dark speckles, while the lower belly and hindquarters are covered in reddish-brown fox fur. Two large folded owl wings with mottled tan, white, grey and brown feathers patterned with dark spots and barring lie against the sides of the torso. It stands on two muscular fox hind legs and has a single long, thick, bushy fox tail extending horizontally behind it with reddish-brown fur and a pale tip.",
  "parts": [
    {
      "part": "head",
      "looks_like": "fox-like head with reddish-brown fur on the crown and cheeks, white fur around the muzzle, chin and lower jaw, a black nose, amber-brown eyes, and fine whiskers; the snout is pointed and the head is turned three-quarters to the right",
      "where": "at the top of the body, above the speckled neck and chest"
    },
    {
      "part": "ears",
      "looks_like": "two large, triangular, pointed fox ears with reddish-brown outer fur, pale inner edges and dark brown to black interior fur, held upright",
      "where": "on top of the head, one on each side of the crown"
    },
    {
      "part": "legs",
      "looks_like": "two muscular hind legs covered in reddish-brown fox fur with lighter tan on the inner thigh and belly, bent at the hock in a crouching stance, with visible joints and dense fur",
      "where": "below the torso, extending from the lower body to the ground, supporting the animal's weight"
    },
    {
      "part": "feet",
      "looks_like": "two hind paws with dark brown fur, distinct toe pads and short light-colored claws, the soles in contact with the ground",
      "where": "at the bottom ends of the hind legs, on the small patch of ground"
    },
    {
      "part": "tail",
      "looks_like": "one long, thick and very bushy fox tail with long reddish-brown fur that becomes paler, almost white, at the tip",
      "where": "extending from the rear of the hindquarters, projecting horizontally to the right behind the legs, low near the ground"
    },
    {
      "part": "wings",
      "looks_like": "two large folded owl wings with layered flight feathers patterned in tan, cream, white and grey with dark brown spots and black barring; the wing on the viewer's left is seen in full side view, the opposite wing is partially visible behind the chest",
      "where": "attached to the sides of the torso at shoulder level, folded against the body and covering the mid-back and sides"
    },
    {
      "part": "feathers",
      "looks_like": "dense, soft owl plumage covering the throat, chest, front and shoulders, white and pale buff with many small dark brown speckles, with larger mottled brown-grey and buff coverts on the wings",
      "where": "on the neck, chest, front of the body and on the wings, transitioning to fox fur at the neck and lower belly"
    },
    {
      "part": "markings",
      "looks_like": "small dark brown to black spots scattered over the white and buff chest and wing covert feathers, and dark horizontal bars and spots on the cream-colored flight feathers and tail feathers of the wings",
      "where": "across the chest plumage and across both wings, most concentrated on the upper wing coverts and the lower edge of the folded wings"
    }
  ],
  "attached_objects": [],
  "animals": ["fox", "owl"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
